import sys
from bisect import bisect_left
from functools import reduce

def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    Q = int(input_data[0])

    # We need to parse the queries. Since they have variable lengths, 
    # we use a generator or a custom iterator to group them.
    def get_queries(data):
        it = iter(data[1:])
        while True:
            try:
                q_type = next(it)
                if q_type == '1':
                    yield (1, 0)
                elif q_type == '2':
                    yield (2, int(next(it)))
                elif q_type == '3':
                    yield (3, int(next(it)))
            except StopIteration:
                break

    # State consists of:
    # 1. current_time: Total T elapsed so far.
    # 2. plants: A sorted list of 't_birth' where height = current_time - t_birth.
    # 3. results: A list to store answers for type 3 queries.

    def process_query(state, query):
        q_type, val = query
        current_time, plants, results = state

        if q_type == 1:
            # Plant height 0 means t_birth = current_time
            # We maintain plants list sorted. Since current_time is non-decreasing,
            # we just append.
            return (current_time, plants + [current_time], results)

        elif q_type == 2:
            # Increase current_time by T
            return (current_time + val, plants, results)

        elif q_type == 3:
            # Harvest plants where height >= H
            # height = current_time - t_birth >= H  =>  t_birth <= current_time - H
            threshold = current_time - val
            # Find how many plants have t_birth <= threshold
            idx = bisect_left(plants, threshold + 1) # First index > threshold
            # The number of harvested plants is idx.
            # The remaining plants are those from idx onwards.
            return (current_time, plants[idx:], results + [idx])

        return state

    # Using reduce to iterate through queries without a for/while loop
    final_state = reduce(process_query, get_queries(input_data), (0, [], []))

    # Print results using join and map to avoid for loop
    sys.stdout.write("\n".join(map(str, final_state[2])) + "\n")

if __name__ == "__main__":
    solve()
